.m10-brush-settings .checkbox-line{display:flex;align-items:center;gap:5px}
#documentInfoDialog textarea{width:100%;box-sizing:border-box;font:inherit}
#documentInfoDialog h3{margin-bottom:4px}
#canvasTemplateForm{border-top:1px solid var(--a-border);margin-top:12px}
#canvasTemplateForm label{display:inline-flex;flex-wrap:wrap;align-items:center;gap:6px}
.pixel-grid{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:.65;z-index:1}
.pixel-grid[hidden]{display:none!important;pointer-events:none}
.pixel-coordinates{position:absolute;right:8px;bottom:8px;z-index:1;background:#fff;color:#27354b;padding:3px 7px;border-radius:4px;pointer-events:none;font-variant-numeric:tabular-nums}
.brush-cursor{position:absolute;top:0;left:0;box-sizing:border-box;border:1px solid #151b2a;box-shadow:0 0 0 1px #fff;border-radius:50%;pointer-events:none;z-index:2}
.brush-cursor::after{content:"";position:absolute;left:50%;top:50%;width:3px;height:3px;border-radius:50%;background:#151b2a;box-shadow:0 0 0 1px #fff;transform:translate(-50%,-50%)}

#maskThumbnail { padding: 2px; vertical-align: middle; }
#maskThumbnail[aria-pressed="true"] { outline: 2px solid #43bfea; outline-offset: 2px; }
#maskThumbnail canvas { display: block; width: 48px; height: 48px; }
#maskEditingBar:not([hidden]), #historyBrushBar:not([hidden]) { display: flex; flex-wrap: wrap; gap: .35rem; align-items: center; }
#historyBrushBar > .workspace-range { flex: 0 1 190px; margin: 0; }
#maskEditingBar button[aria-pressed="true"] { outline: 2px solid #43bfea; outline-offset: -2px; }

.layer-blend-dialog { position: fixed; inset: auto auto 1rem 1rem; z-index: 30; max-width: min(90vw, 26rem); }
.layer-blend-dialog form { display: grid; gap: .6rem; }
.layer-blend-dialog label { display: flex; gap: .6rem; align-items: center; justify-content: space-between; }
.layer-blend-dialog menu { display: flex; gap: .6rem; margin: 0; padding: 0; }

.layer-pick-dialog fieldset { display: grid; gap: .35rem; max-height: 40dvh; overflow: auto; }
.layer-pick-dialog label { justify-content: flex-start; }

#layerDrawingThumbnail { width: 36px; height: 36px; vertical-align: middle; background: #dedfe2; border: 1px solid #9998; }
.brush-cursor[data-tip-mask] { border: 0; box-shadow: none; }
.brush-cursor[data-tip-mask]::before {
  content: "";
  position: absolute;
  inset: 0;
  background: #10122077;
  mask: var(--brush-cursor-mask) 50% / 100% 100% no-repeat;
  outline: 1px solid white;
}

ui/workspaceControls.css:
select.workspace-choice-source { display: none !important }
.workspace-choice {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  max-width: 100%;
  min-height: 40px;
  padding-inline: 6px;
  text-align: start;
  border: 0;
  border-bottom: 1px solid var(--a-border-strong, #a5b0c3);
  border-radius: 0;
  background: transparent;
  color: inherit;
}
.workspace-choice > span { min-width: 0; overflow-wrap: anywhere }
.workspace-choice .ui-icon { flex: none; width: 16px; height: 16px }
.workspace-choice[hidden], .workspace-options:not(:popover-open) { display: none }
.workspace-options {
  position: fixed;
  inset: auto;
  margin: 0;
  padding: 4px;
  box-sizing: border-box;
  overflow: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  background: var(--a-surface, #fff);
  color: var(--a-text, #222c40);
  border: 1px solid var(--a-border, #c7d0df);
  border-radius: 9px;
  box-shadow: 0 8px 26px #19294330;
}
.workspace-options [role=option] {
  display: flex;
  align-items: center;
  min-height: 42px;
  padding: 4px 8px;
  border-radius: 5px;
  cursor: pointer;
}
.workspace-options [role=option][aria-selected=true] { font-weight: 700 }
.workspace-options [role=option][aria-selected=true]::before { content: '✓'; margin-inline-end: 6px }
.workspace-options [role=option][aria-disabled=true] { opacity: .47; cursor: default }
.workspace-options [role=option].active { outline: 2px solid var(--a-focus, #565aad); outline-offset: -2px }
.workspace-range:not([hidden]) {
  display: grid;
  grid-template-columns: var(--range-step-width, 36px) minmax(0, 1fr) var(--range-step-width, 36px);
  gap: 0 5px;
  align-items: center;
  min-width: 0;
}
.workspace-range-from-label { margin-block: 5px; font-size: 13px }
.workspace-range-header {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-width: 0;
}
.workspace-range .workspace-range-header > label {
  display: block;
  min-width: 0;
  margin: 0;
  font-size: inherit;
  overflow-wrap: anywhere;
}
.workspace-range-value {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  color: inherit;
  font-variant-numeric: tabular-nums;
}
.workspace-range-value > input[type=number] {
  appearance: textfield;
  width: 7ch;
  min-height: 30px;
  margin: 0;
  padding: 0 3px;
  text-align: end;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 4px;
  cursor: text;
}
.workspace-range-value > input[type=number]::-webkit-inner-spin-button,
.workspace-range-value > input[type=number]::-webkit-outer-spin-button { appearance: none; margin: 0 }
.workspace-range-value > input[type=number]:focus {
  background: var(--a-surface, #fff);
  outline: 1px solid var(--a-focus, #565aad);
  outline-offset: -1px;
}
.workspace-range-value > input[type=number]:focus-visible { outline-width: 2px }
.workspace-range-value > input[type=number]:disabled { opacity: .55; cursor: default }
.workspace-range > input[type=range] { grid-area: 2 / 2; width: 100%; min-width: 0; min-height: 28px; margin: 0 }
/* Keep legacy output nodes for existing value updates, but never render duplicate values below the slider. */
.workspace-range > output { display: none !important }
.workspace-range-minus, .workspace-range-plus { grid-row: 2; min-height: 36px; padding: 0 }
.workspace-range-minus { grid-column: 1 }
.workspace-range-plus { grid-column: 3 }

color/color.css:
/* M09 Color / Aurora. The first interaction is choosing a color.
 * Secondary settings use native disclosures; never squeeze four parallel tabs into a narrow dock.
 * The SV square and its handle are mathematically INSIDE the hue ring's empty center.
 */
.color-workbench{min-width:0;display:flex;flex-direction:column;gap:12px;padding:3px 0 6px;color:var(--a-text)}
.color-workbench *{box-sizing:border-box}
.color-current{display:grid;grid-template-columns:46px minmax(0,1fr) 34px auto;align-items:center;gap:9px;padding:10px 9px;border-radius:12px;background:var(--a-surface-soft);border:1px solid var(--a-border)}
.color-chip{display:block;width:46px;height:43px;min-width:0;min-height:0;padding:0;border-radius:10px;border:2px solid white;box-shadow:0 0 0 1px var(--a-border-strong),0 2px 6px #30425928;cursor:pointer}
.color-chip:focus-visible{outline:3px solid var(--a-focus);outline-offset:3px}
.color-previous{width:34px;height:34px;border-radius:8px}
.color-previous-label{font-size:10px;white-space:nowrap;color:var(--a-subtle)}
.color-describe{display:flex;flex-direction:column;gap:4px;min-width:0}
.color-describe strong{font-size:11px;font-weight:650;color:var(--a-subtle)}
.color-describe output{font-size:14px;font-weight:750;letter-spacing:.03em;font-variant-numeric:tabular-nums;white-space:nowrap}
.color-primary{display:flex;flex-direction:column;gap:7px}
.color-picker{position:relative;width:min(252px,100%);height:auto;aspect-ratio:1;margin:2px auto 3px;touch-action:none;user-select:none;isolation:isolate}
/* Use closest-side (actual circle radius) for the mask. The former farthest-corner percentage stop made the color band too wide. */
.color-ring{--hue-ring-width:22px;position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 90deg,#ff0000,#ffff00,#00ff00,#00ffff,#0000ff,#ff00ff,#ff0000);-webkit-mask:radial-gradient(circle closest-side at center,transparent calc(100% - var(--hue-ring-width) - 1px),#000 calc(100% - var(--hue-ring-width)));mask:radial-gradient(circle closest-side at center,transparent calc(100% - var(--hue-ring-width) - 1px),#000 calc(100% - var(--hue-ring-width)));touch-action:none}
/* Visual cutout fallback for engines that do not support CSS masks. */
.color-ring::after{content:"";position:absolute;inset:var(--hue-ring-width);border-radius:50%;background:var(--a-surface);pointer-events:none}
.color-ring:focus-visible{outline:3px solid var(--a-focus);outline-offset:4px}
.color-ring-marker{position:absolute;left:94%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 1.5px #263144,0 1px 5px #26314488;z-index:2;pointer-events:none}
.color-plane{position:absolute;left:27%;top:27%;width:46%;height:46%;border-radius:8px;background:var(--pure,#ff0000);box-shadow:0 1px 4px #16294d3b,0 0 0 1px #cad3df;touch-action:none;cursor:crosshair}
.color-plane-white,.color-plane-black{position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.color-plane-white{background:linear-gradient(to right,#fff,transparent)}
.color-plane-black{background:linear-gradient(to top,#000,transparent)}
.color-sv-marker{position:absolute;left:0;top:0;width:18px;height:18px;transform:translate(-50%,-50%);border:3px solid white;border-radius:50%;box-shadow:0 0 0 1.5px #2e3a4e,0 1px 5px #18223c80;pointer-events:none}
.color-precision-inline{display:grid;grid-template-columns:minmax(0,1fr) minmax(82px,auto);gap:8px;align-items:end;margin:0}
.color-precision-inline label{min-width:0;display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:650;color:var(--a-subtle)}
.color-precision-inline input{width:100%;min-width:0;min-height:42px;padding:7px 10px;border:1px solid var(--a-border-strong);border-radius:9px;background:#fff;color:var(--a-text);font-variant-numeric:tabular-nums;letter-spacing:.035em;font-size:14px}
.color-pick-button{min-height:42px;padding:7px 10px;border:1px solid var(--a-border-strong);border-radius:9px;background:var(--a-surface-soft);color:var(--a-text);font-weight:650;font-size:12px}
.color-pick-button:hover{background:var(--a-accent-soft)}
.color-recent,.color-library{min-width:0}
.color-section-header{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:7px}
.color-section-header h3{margin:0;font-size:12px;letter-spacing:.005em;font-weight:750}
.color-add-button{min-height:36px;padding:6px 8px;border:1px solid var(--a-border-strong);background:var(--a-surface-soft);border-radius:8px;color:var(--a-text);font-size:11px;font-weight:650;white-space:nowrap}
.color-add-button:hover{background:var(--a-accent-soft)}
.color-swatch-grid{display:grid;min-width:0;gap:7px;overflow-y:auto;overscroll-behavior:contain;padding:3px 2px 5px}
.color-swatch{display:block;width:100%;height:39px;min-height:39px;min-width:0;padding:0;border:2px solid white;border-radius:9px;box-shadow:0 0 0 1px var(--a-border-strong);cursor:pointer;transition:box-shadow .12s}
.color-swatch[aria-pressed=true]{box-shadow:0 0 0 2.5px var(--a-focus),0 1px 5px #303f6440}
.color-swatch:focus-visible{outline:3px solid var(--a-focus);outline-offset:3px}
.color-history-strip{display:flex;align-items:center;gap:8px;min-height:47px;max-height:52px;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin}
.color-history-strip .color-swatch{flex:0 0 38px;width:38px;height:38px}
.color-empty{display:block;grid-column:1/-1;min-width:0;padding:8px 2px;font-size:11px;line-height:1.45;color:var(--a-subtle)}
.color-palette-choice{display:flex;align-items:center;gap:7px;margin:0 0 8px;font-size:11px;color:var(--a-subtle)}
.color-palette-choice>span{flex:none}
.color-palette-choice select{width:100%;min-width:0;min-height:38px;border-radius:8px;border:1px solid var(--a-border-strong);background:#fff;font-size:12px;padding:5px 9px;color:var(--a-text)}
.color-favorites-grid{grid-template-columns:repeat(auto-fill,minmax(38px,1fr));max-height:112px;gap:8px;padding:4px 3px 6px}
.color-favorites-grid .color-swatch{height:40px;min-height:40px}
.color-disclosure{min-width:0;border-top:1px solid var(--a-border);margin-top:2px}
.color-disclosure>summary{cursor:pointer;list-style:none;position:relative;display:flex;align-items:center;justify-content:space-between;min-height:42px;gap:8px;padding:10px 23px 10px 2px;font-size:12px;font-weight:650;color:var(--a-subtle);touch-action:manipulation}
.color-disclosure>summary::-webkit-details-marker{display:none}
.color-disclosure>summary::after{content:"";width:7px;height:7px;position:absolute;right:8px;top:17px;border-right:1.7px solid currentColor;border-bottom:1.7px solid currentColor;transform:rotate(45deg);transition:transform .15s}
.color-disclosure[open]>summary{color:var(--a-text)}
.color-disclosure[open]>summary::after{transform:rotate(225deg);top:19px}
.color-disclosure>summary:focus-visible{outline:2px solid var(--a-focus);outline-offset:1px;border-radius:7px}
.color-detail-inner{padding:4px 2px 9px}
.color-models{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;padding:4px;background:var(--a-surface-soft);border-radius:10px;margin:0 0 12px}
.color-models label{display:block;min-width:0;margin:0;position:relative}
.color-models input{position:absolute;opacity:0;inset:0;width:100%;height:100%;margin:0}
.color-models span{display:block;text-align:center;padding:9px 4px;min-height:38px;font-weight:650;font-size:12px;border-radius:8px}
.color-models input:checked+span{background:#fff;box-shadow:0 1px 4px #2d3e5820;color:var(--a-text)}
.color-models input:focus-visible+span{outline:3px solid var(--a-focus)}
.color-value-channels{display:grid;gap:10px}
.color-value-row label{margin:0;font-size:11px}
.color-value-row input[type=range]{margin:0;min-width:0;accent-color:var(--a-accent);height:32px;touch-action:pan-y}
.color-unit{font-size:10px;color:var(--a-subtle)}
.color-palette-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin:6px 0 10px}
.color-palette-actions button{min-height:40px;padding:6px;font-size:11px;white-space:normal;border:1px solid var(--a-border-strong);border-radius:8px;background:var(--a-surface-soft)}
.color-help{font-size:11px;color:var(--a-subtle);line-height:1.55;margin:7px 0}
.color-manage-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:10px;max-height:330px;overflow-y:auto;padding:4px}
.color-swatch-cell{min-width:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}
.color-swatch-cell .color-swatch{grid-column:1/-1}
.color-swatch-move{min-width:0;width:100%;min-height:38px;padding:3px;border-radius:7px;font-weight:650;font-size:13px}
.color-sample-source{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;font-weight:650}
.color-sample-source select{margin:0;width:66%;min-height:40px;font-size:11px;padding:5px;border:1px solid var(--a-border-strong);border-radius:8px}
.color-error{display:block;font-size:11px;color:#963649;min-height:0;line-height:1.4}
.color-error:empty{display:none}
.color-palette-notice{font-size:11px;color:var(--a-focus);line-height:1.4}
.color-palette-notice:empty{display:none}
.color-palette-dialog{border:1px solid var(--a-border-strong);border-radius:15px;padding:18px;width:min(360px,calc(100vw - 28px));max-width:calc(100vw - 28px);box-shadow:0 15px 55px #26395545;background:#fff;color:var(--a-text)}
.color-palette-dialog::backdrop{background:#26365482}
.color-palette-dialog h3{font-size:17px;letter-spacing:-.02em;margin:0 0 12px}
.color-palette-dialog label{font-size:13px;font-weight:600}
.color-palette-dialog input{display:block;width:100%;min-height:42px;margin-top:8px;border:1px solid var(--a-border-strong);border-radius:9px;padding:8px 10px}
.color-dialog-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:13px}
.color-dialog-actions button{min-height:42px;padding:8px 15px}
#colorPaletteConfirm{background:var(--a-accent-soft);font-weight:700}
.color-sample-loupe{position:fixed;z-index:25;min-width:144px;background:#fffefbf0;border:1px solid var(--a-border-strong,#cdd7e8);box-shadow:0 5px 22px #15223b42;border-radius:12px;padding:8px;pointer-events:none;font-size:11px}
.color-sample-loupe[hidden]{display:none!important}
.color-sample-loupe>strong{display:block;text-align:center;font-size:11px;margin-bottom:5px}
.color-loupe-pair{display:flex;gap:6px}
.color-loupe-pair span{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:9px;white-space:nowrap}
.color-loupe-pair i{display:block;width:46px;height:42px;border-radius:8px;border:2px solid #fff;box-shadow:0 0 0 1px #8895a8}
.color-sample-loupe small{display:block;text-align:center;letter-spacing:.08em;font-variant-numeric:tabular-nums;margin-top:4px}
@media(any-pointer:coarse){
 .color-swatch{height:44px;min-height:44px}
 .color-history-strip{min-height:51px;max-height:55px}
 .color-history-strip .color-swatch{height:44px;width:44px;flex-basis:44px}
 .color-favorites-grid{grid-template-columns:repeat(auto-fill,minmax(42px,1fr));max-height:120px}
 .color-favorites-grid .color-swatch{height:44px}
 .color-disclosure>summary{min-height:44px}
 .color-add-button{min-height:42px}
 .color-swatch-move{min-height:44px}
}
@media(max-width:370px){.color-current{gap:6px;padding:8px 6px}.color-previous-label{font-size:9px}.color-workbench{gap:10px}}
@media(prefers-reduced-motion:reduce){.color-swatch,.color-disclosure>summary::after{transition:none}}


/* M09 ibisPaint reference (official Color Window tutorial):
 * Current/Previous → Color or Palette → wheel+diamond / swatches → HSB/RGB.
 * Aurora colors remain consistent with the editor, but no bespoke color-navigation UI.
 */
.color-mode-switch{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px;padding:3px;border-radius:9px;background:var(--a-surface-soft);border:1px solid var(--a-border);margin:1px 0 2px}
.color-mode-switch button{min-width:0;min-height:42px;padding:8px 5px;border:0;border-radius:7px;background:transparent;color:var(--a-subtle);font-size:12px;font-weight:650}
.color-mode-switch button[aria-selected=true]{background:#fff;color:var(--a-text);box-shadow:0 1px 4px #2d3e581e}
.color-mode-switch button:focus-visible{outline:2px solid var(--a-focus);outline-offset:-2px}
#colorScreen[hidden],#colorPaletteScreen[hidden]{display:none!important}
#colorScreen{display:flex;flex-direction:column;gap:9px;min-width:0}
#colorPaletteScreen{display:flex;flex-direction:column;gap:9px;min-width:0}
.color-picker{margin:4px auto 6px}
.color-ring{cursor:crosshair}
.color-plane{
 width:47%;height:47%;left:26.5%;top:26.5%;
 transform:rotate(45deg);transform-origin:center;
 border-radius:3px;overflow:visible;
}
/* A circle is unaffected by the parent square's rotation. */
.color-sv-marker{transform:translate(-50%,-50%);width:18px;height:18px}
.color-plane-white,.color-plane-black{border-radius:3px}
.color-hex-label{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:0;font-size:12px;font-weight:650;color:var(--a-text)}
.color-hex-label input{min-width:0;width:126px;max-width:58%;height:39px;min-height:39px;margin:0;padding:6px 8px;background:#fff;border:1px solid var(--a-border-strong);border-radius:7px;font-size:13px;letter-spacing:.035em;text-align:center;font-variant-numeric:tabular-nums}
.color-value-channels{margin-top:3px;gap:9px}
.color-value-row input[type=range]{cursor:pointer}
.color-value-footer{display:flex;align-items:center;justify-content:space-between;gap:7px;border-top:1px solid var(--a-border);padding-top:10px}
.color-mode-caption{font-size:10px;color:var(--a-subtle);white-space:nowrap}
.color-models{min-width:0;flex:1;max-width:222px;margin:0;gap:3px}
.color-models span{padding:8px 2px;min-height:36px;font-size:11px}
.color-value-row label{font-size:11px}
.color-section-header h3{font-size:12px}
.color-palette-screen .color-favorites-grid{grid-template-columns:repeat(auto-fill,minmax(36px,1fr));max-height:256px;min-height:55px;overflow-y:auto;gap:7px}
.color-palette-screen .color-history-strip{display:grid;grid-template-columns:repeat(auto-fill,minmax(37px,1fr));gap:7px;max-height:158px;overflow-x:hidden;overflow-y:auto;min-height:55px;padding:4px 3px 8px}
.color-palette-screen .color-history-strip .color-swatch{width:100%;height:39px;min-height:39px}
.color-history-heading{padding-top:8px;border-top:1px solid var(--a-border);margin-top:4px}
.color-workbench .color-disclosure{margin-top:3px}
@media(any-pointer:coarse){
 .color-mode-switch button{min-height:44px}
 .color-hex-label input{min-height:42px}
 .color-palette-screen .color-history-strip .color-swatch{height:44px;min-height:44px}
}


/* M09: compact mode switch shared by Classic and Orbit. */
.color-mode-switch{grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,96px);gap:3px}
.color-mode-switch.color-no-picker-mode{grid-template-columns:repeat(2,minmax(0,1fr))}
.color-mode-switch #colorPickerMode{appearance:auto;box-sizing:border-box;min-width:0;width:100%;height:40px;min-height:40px;align-self:center;border:1px solid var(--a-border-strong);border-radius:7px;padding:0 2px 0 6px;background:#fff;color:var(--a-text);font-size:11px;font-weight:650;cursor:pointer}
.color-mode-switch #colorPickerMode:focus-visible{outline:2px solid var(--a-focus);outline-offset:1px}
.color-mode-switch #colorPickerMode[hidden]{display:none!important}
#colorPicker[hidden],#colorOrbitPicker[hidden]{display:none!important}

/* Proper 3D composition: back rim < SV diamond < front rim.
   Both rims share one paint operation for consistent colors and geometry. */
.color-orbit-picker{
 position:relative;width:min(306px,100%);height:auto;aspect-ratio:1;
 min-width:0;margin:2px auto 3px;overflow:hidden;user-select:none;
 isolation:isolate;touch-action:pan-y;
}
.color-orbit-plane{
 position:absolute;z-index:2;
 top:23%;left:27.75%;width:44.5%;height:auto;aspect-ratio:1;
 box-sizing:border-box;transform:rotate(45deg);transform-origin:center;
 border:1px solid rgba(52,69,94,.5);border-radius:3px;
 background:var(--pure,#f33);
 box-shadow:0 1px 5px rgba(30,48,73,.18),0 0 0 2px rgba(255,255,255,.88);
 touch-action:none;cursor:crosshair;overflow:visible;
}
.color-orbit-white,.color-orbit-black{position:absolute;inset:0;pointer-events:none;border-radius:inherit}
.color-orbit-white{background:linear-gradient(to right,#fff,transparent)}
.color-orbit-black{background:linear-gradient(to top,#000,transparent)}
.color-orbit-sv-marker{
 position:absolute;z-index:3;width:17px;height:17px;border-radius:50%;
 border:3px solid #fff;box-shadow:0 0 0 1.4px #263344,0 1px 4px #23344880;
 transform:translate(-50%,-50%);pointer-events:none;
}
/* Canvas transparency exposes the diamond underneath the inner opening.
   The colored ring itself is in front, so it can be traced all the way around. */
.color-orbit-wheel{
 position:absolute;z-index:0;left:0;top:48%;width:100%;
 height:auto;aspect-ratio:2/1;display:block;
 pointer-events:none;touch-action:pan-y;outline:none;
}
/* SVG input layers follow the visible back/SV/front order.
   Front hue wins above SV; only exposed back hue is clickable. */
.color-orbit-wheel-front{z-index:3}
.color-orbit-hue-hit{
 position:absolute;left:0;top:48%;width:100%;
 height:auto;aspect-ratio:2/1;display:block;overflow:visible;
 pointer-events:none;touch-action:none;
}
.color-orbit-hue-back{z-index:1}
.color-orbit-hue-front{z-index:4}
.color-orbit-hue-hit path{pointer-events:fill;touch-action:none;cursor:grab}
.color-orbit-hue-hit path:active{cursor:grabbing}
/* Never inherit the global opaque canvas background. */
#colorOrbitWheel.color-orbit-wheel,
#colorOrbitWheelFront.color-orbit-wheel{background:transparent}
.color-orbit-wheel:active{cursor:grabbing}
.color-orbit-wheel:focus-visible{outline:3px solid var(--a-focus);outline-offset:-3px;border-radius:35%}
.color-orbit-hint{
 position:absolute;left:0;right:0;bottom:0;line-height:17px;
 text-align:center;font-size:10px;color:var(--a-subtle);pointer-events:none;
}
@media(any-pointer:coarse){.color-mode-switch #colorPickerMode{height:44px;min-height:44px}}

.color-mode-switch { grid-template-columns: repeat(2,minmax(0,1fr)) }
.color-models { display: flex; margin-block: 6px; gap: 2px }
.color-models button, .color-mode-switch button {
  flex: 1;
  min-height: 42px;
  padding: 4px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
}
.color-models button[aria-selected=true], .color-mode-switch button[aria-selected=true] {
  border-bottom-color: var(--a-focus);
  background: var(--a-accent-soft);
}
.color-palette-screen :is(.color-favorites-grid,.color-history-strip) {
  max-height: none;
  overflow: visible;
  touch-action: pan-y;
  overscroll-behavior: auto;
}
.color-palette-screen .color-swatch { touch-action: pan-y }
#colorEyedropperOptions { width: min(400px, calc(100vw - 24px)); padding: 14px; border: 1px solid var(--a-border); border-radius: 12px; }
#colorEyedropperOptions h3 { margin-block-start: 0 }
#colorEyedropperOptions button { min-height: 44px }

ui/brushEditor.css:
/* M10: settings live inside the existing right Brush box, never a modal overlay. */
.brush-edit-feedback{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin:6px 0;color:#66758c;font-size:12px}
.brush-edit-feedback button{font:inherit;padding:5px 9px;border-radius:8px;border:1px solid #c9d6ea;background:#f7faff;color:#2c4b78;cursor:pointer}
.brush-edit-feedback button:disabled{opacity:.5;cursor:default}
.brush-editor-advanced{margin:10px 0 4px;display:flex;flex-direction:column;gap:7px;min-width:0}
.brush-editor-section{border:1px solid #dce5f1;border-radius:11px;background:#fafcff;min-width:0;overflow:clip}
.brush-editor-section summary{cursor:pointer;user-select:none;padding:11px 12px;font-size:13px;font-weight:650;color:#304461;list-style-position:inside;touch-action:manipulation}
.brush-editor-section summary:focus-visible{outline:2px solid #728eef;outline-offset:-2px}
.brush-editor-section[open] summary{border-bottom:1px solid #e0e8f2}
.brush-editor-section-body{display:flex;flex-direction:column;gap:11px;padding:11px 12px 14px;min-width:0;font-size:12px}
.brush-editor-section-body p{color:#66758c;line-height:1.5;margin:0}
.brush-editor-section-body>label{display:flex;align-items:center;justify-content:space-between;gap:9px;min-width:0;font-size:12px}
.brush-editor-section-body>label select{flex:1;min-width:0;max-width:65%;padding:6px;border-radius:8px;border:1px solid #cbd7e6;background:#fff}
.brush-editor-section-body>label.checkbox-line{justify-content:flex-start}
.brush-editor-control{min-width:0;display:flex;flex-direction:column;gap:5px}
.brush-curve-chart{width:min(100%,228px);aspect-ratio:1;background:linear-gradient(0deg,#f4f7ff,#fff);border:1px solid #c8d5ed;border-radius:9px;display:block;touch-action:none;cursor:crosshair;margin:auto}
.brush-curve-grid{stroke:#d9e3f5;stroke-width:1;fill:none}
.brush-curve-line{stroke:#456bc6;stroke-width:2.5;fill:none;stroke-linejoin:round}
.brush-curve-point{fill:#fff;stroke:#456bc6;stroke-width:2}
.brush-curve-point.selected{fill:#456bc6;stroke:#fff;stroke-width:2.5}
.brush-curve-actions{display:flex;flex-wrap:wrap;align-items:center;gap:5px}
.brush-curve-actions select{min-width:68px;max-width:100px;padding:5px;border:1px solid #cbd7e6;border-radius:7px}
.brush-curve-actions button{border:1px solid #c7d3e7;border-radius:7px;background:#fff;color:#31456a;min-height:31px;padding:5px 7px;cursor:pointer;font-size:11px}
.brush-curve-actions button:disabled{opacity:.45;cursor:default}
.brush-curve-coordinates{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.brush-curve-coordinates label{display:flex;align-items:center;gap:4px}
.brush-curve-coordinates input{width:100%;min-width:0;padding:5px;border:1px solid #cbd7e6;border-radius:7px;font-variant-numeric:tabular-nums}
@media(max-width:600px){.brush-editor-section summary{padding:12px}.brush-editor-section-body{padding:12px}}

/* M10 Dynamics editor: compact touch-friendly controls inside the Brush box. */
#brushDynamicsList{display:flex;flex-direction:column;gap:7px}
.brush-dynamics-row,.brush-dynamics-add{display:flex;flex-wrap:wrap;align-items:center;gap:7px;padding:8px;border:1px solid #dce5f1;border-radius:8px;background:#fff;font-size:12px}
.brush-dynamics-row label{display:inline-flex;align-items:center;gap:5px;font-size:12px}
.brush-dynamics-row input{width:62px;min-width:0;padding:5px;border:1px solid #ccd9e7;border-radius:7px}
.brush-dynamics-row select,.brush-dynamics-add select{min-width:78px;flex:1;padding:6px;border:1px solid #ccd9e7;border-radius:7px;background:#fff;color:#304461}
.brush-dynamics-row button,.brush-dynamics-add button{border:1px solid #c5d3e7;background:#f6f9ff;border-radius:7px;min-height:33px;padding:6px 9px;color:#304461;cursor:pointer}
.brush-dynamics-add button{flex:1}
